import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import { dirname } from 'node:path';
import { randomBytes } from 'node:crypto';

// Keeps the book list in memory and mirrors every change to a JSON file.
export async function openStore(filePath) {
  let books = await load(filePath);
  // Chain writes so two quick changes can't interleave and clobber each other.
  let pending = Promise.resolve();

  function persist() {
    const snapshot = JSON.stringify({ books }, null, 2);
    pending = pending.then(() => save(filePath, snapshot));
    return pending;
  }

  function newId() {
    let id;
    do {
      id = randomBytes(6).toString('base64url');
    } while (books.some((b) => b.id === id));
    return id;
  }

  return {
    all() {
      return books.map((b) => ({ ...b }));
    },

    get(id) {
      const book = books.find((b) => b.id === id);
      return book ? { ...book } : undefined;
    },

    async add({ title, author, notes }) {
      const book = {
        id: newId(),
        title,
        author,
        notes,
        status: 'reading',
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books = [...books, book];
      await persist();
      return { ...book };
    },

    async finish(id) {
      const book = books.find((b) => b.id === id);
      if (!book) return undefined;
      if (book.status !== 'finished') {
        books = books.map((b) =>
          b.id === id ? { ...b, status: 'finished', finishedAt: new Date().toISOString() } : b,
        );
        await persist();
      }
      return this.get(id);
    },
  };
}

async function load(filePath) {
  let text;
  try {
    text = await readFile(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  // A corrupt file is left alone rather than silently replaced with an empty list.
  const data = JSON.parse(text);
  if (!Array.isArray(data.books)) {
    throw new Error(`${filePath} does not contain a "books" array`);
  }
  return data.books;
}

// Write to a temp file and rename, so a crash mid-write never leaves a half-written file.
async function save(filePath, text) {
  await mkdir(dirname(filePath), { recursive: true });
  const tmp = `${filePath}.tmp`;
  await writeFile(tmp, text);
  await rename(tmp, filePath);
}

