export function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

const styles = `
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  h1 a { color: inherit; text-decoration: none; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .author { color: #666; }
  .empty { color: #888; font-style: italic; }
  form.add { display: grid; gap: .5rem; }
  form.add input, form.add textarea { font: inherit; padding: .4rem; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: .75rem; border-radius: 4px; }
  .error { color: #b00020; }
  .share input { width: 100%; font: inherit; padding: .4rem; }
  button { font: inherit; cursor: pointer; }
`;

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>${styles}</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const finishButton =
    book.status === 'reading'
      ? `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
          <button type="submit">Mark finished</button>
        </form>`
      : '';
  return `<li>
    <span><a href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>
    ${book.author ? `<span class="author">by ${escapeHtml(book.author)}</span>` : ''}</span>
    ${finishButton}
  </li>`;
}

function bookList(books, emptyText) {
  if (books.length === 0) return `<p class="empty">${escapeHtml(emptyText)}</p>`;
  return `<ul class="books">${books.map(bookItem).join('')}</ul>`;
}

export function homePage({ reading, finished, error, form = {} }) {
  return layout(
    'My books',
    `
<h2>Currently reading</h2>
${bookList(reading, 'Nothing on the go right now.')}

<h2>Finished</h2>
${bookList(finished, 'No finished books yet.')}

<h2>Add a book</h2>
${error ? `<p class="error">${escapeHtml(error)}</p>` : ''}
<form class="add" method="post" action="/books">
  <label>Title <input name="title" required maxlength="500" value="${escapeHtml(form.title)}"></label>
  <label>Author <input name="author" maxlength="500" value="${escapeHtml(form.author)}"></label>
  <label>Notes <textarea name="notes" rows="4" maxlength="20000">${escapeHtml(form.notes)}</textarea></label>
  <button type="submit">Add book</button>
</form>`,
  );
}

export function bookPage(book, shareUrl) {
  const finishedLine =
    book.status === 'finished'
      ? `<p>Finished on ${escapeHtml(book.finishedAt.slice(0, 10))}</p>`
      : `<p>Currently reading</p>
         <form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
           <button type="submit">Mark finished</button>
         </form>`;
  return layout(
    book.title,
    `
<h2>${escapeHtml(book.title)}</h2>
<p class="author">${book.author ? `by ${escapeHtml(book.author)}` : 'Author unknown'}</p>
${finishedLine}

<h3>Notes</h3>
${book.notes ? `<div class="notes">${escapeHtml(book.notes)}</div>` : '<p class="empty">No notes.</p>'}

<h3>Share</h3>
<p class="share"><label>Link to this book <input readonly value="${escapeHtml(shareUrl)}" onfocus="this.select()"></label></p>`,
  );
}

export function notFoundPage() {
  return layout('Not found', `<p>That book doesn't exist. <a href="/">Back to your books</a></p>`);
}

