import { homePage, bookPage, notFoundPage } from './views.js';

const MAX_BODY_BYTES = 64 * 1024;
const LIMITS = { title: 500, author: 500, notes: 20000 };

// Returns a (req, res) handler. `publicUrl` overrides the host used in share links.
export function createApp({ store, publicUrl }) {
  return async function handle(req, res) {
    try {
      await route(req, res);
    } catch (err) {
      if (err.status) {
        send(res, err.status, err.message, 'text/plain; charset=utf-8');
      } else {
        console.error(err);
        send(res, 500, 'Something went wrong.', 'text/plain; charset=utf-8');
      }
    }
  };

  async function route(req, res) {
    const url = new URL(req.url, 'http://localhost');
    const path = url.pathname;
    let match;

    if (path === '/') {
      if (req.method !== 'GET' && req.method !== 'HEAD') return methodNotAllowed(res, 'GET');
      return send(res, 200, renderHome());
    }

    if (path === '/books') {
      if (req.method !== 'POST') return methodNotAllowed(res, 'POST');
      const form = await readForm(req);
      const book = {
        title: (form.get('title') ?? '').trim(),
        author: (form.get('author') ?? '').trim(),
        notes: (form.get('notes') ?? '').trim(),
      };
      const error = validate(book);
      if (error) return send(res, 400, renderHome({ error, form: book }));
      await store.add(book);
      return redirect(res, '/');
    }

    if ((match = path.match(/^\/books\/([^/]+)$/))) {
      if (req.method !== 'GET' && req.method !== 'HEAD') return methodNotAllowed(res, 'GET');
      const book = store.get(decodeURIComponent(match[1]));
      if (!book) return send(res, 404, notFoundPage());
      return send(res, 200, bookPage(book, shareUrl(req, path)));
    }

    if ((match = path.match(/^\/books\/([^/]+)\/finish$/))) {
      if (req.method !== 'POST') return methodNotAllowed(res, 'POST');
      const id = decodeURIComponent(match[1]);
      const book = await store.finish(id);
      if (!book) return send(res, 404, notFoundPage());
      return redirect(res, backTo(req, `/books/${encodeURIComponent(id)}`));
    }

    return send(res, 404, notFoundPage());
  }

  function renderHome(extra = {}) {
    const books = store.all();
    const reading = books
      .filter((b) => b.status === 'reading')
      .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
    const finished = books
      .filter((b) => b.status === 'finished')
      .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));
    return homePage({ reading, finished, ...extra });
  }

  function shareUrl(req, path) {
    const base = publicUrl || `http://${req.headers.host || 'localhost'}`;
    return new URL(path, base).href;
  }
}

function validate(book) {
  if (!book.title) return 'Please give the book a title.';
  for (const [field, max] of Object.entries(LIMITS)) {
    if (book[field].length > max) return `The ${field} is too long (max ${max} characters).`;
  }
  return null;
}

// After marking a book finished, go back to wherever the button was clicked —
// but only to a page on this site.
function backTo(req, fallback) {
  const referer = req.headers.referer;
  if (!referer) return fallback;
  try {
    const ref = new URL(referer);
    if (ref.host !== req.headers.host) return fallback;
    return ref.pathname === '/' ? '/' : fallback;
  } catch {
    return fallback;
  }
}

async function readForm(req) {
  const type = req.headers['content-type'] || '';
  if (!type.startsWith('application/x-www-form-urlencoded')) {
    throw httpError(415, 'Expected a form submission.');
  }
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw httpError(413, 'That form is too large.');
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function httpError(status, message) {
  return Object.assign(new Error(message), { status });
}

function send(res, status, body, type = 'text/html; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function methodNotAllowed(res, allow) {
  res.setHeader('Allow', allow);
  send(res, 405, 'Method not allowed.', 'text/plain; charset=utf-8');
}

