import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { createServer } from 'node:http';
import { mkdtemp, rm, readFile, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { openStore } from '../src/store.js';
import { createApp } from '../src/app.js';

let dir, dataFile, server, base;

async function start() {
  const store = await openStore(dataFile);
  server = createServer(createApp({ store }));
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  base = `http://127.0.0.1:${server.address().port}`;
}

async function stop() {
  await new Promise((r) => server.close(r));
}

function post(path, fields = {}, headers = {}) {
  return fetch(base + path, {
    method: 'POST',
    body: new URLSearchParams(fields),
    redirect: 'manual',
    headers,
  });
}

async function addBook(fields) {
  const res = await post('/books', fields);
  expect(res.status).toBe(303);
  const saved = JSON.parse(await readFile(dataFile, 'utf8')).books;
  return saved.at(-1);
}

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  dataFile = join(dir, 'books.json');
  await start();
});

afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe('books app', () => {
  it('shows empty sections when there are no books', async () => {
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Nothing on the go right now.');
    expect(html).toContain('No finished books yet.');
  });

  it('adds a book from the form and lists it as currently reading', async () => {
    const book = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.' });
    expect(book).toMatchObject({ title: 'Dune', author: 'Frank Herbert', status: 'reading' });

    const html = await (await fetch(base + '/')).text();
    const [reading, finished] = html.split('<h2>Finished</h2>');
    expect(reading).toContain(`href="/books/${book.id}"`);
    expect(finished).not.toContain('Dune');
  });

  it('marks a book finished and moves it to the finished list', async () => {
    const book = await addBook({ title: 'Dune' });
    const res = await post(`/books/${book.id}/finish`, {}, { referer: `${base}/` });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const html = await (await fetch(base + '/')).text();
    const [reading, finished] = html.split('<h2>Finished</h2>');
    expect(reading).not.toContain('Dune');
    expect(finished).toContain('Dune');
  });

  it('redirects back to the book page when finished from there', async () => {
    const book = await addBook({ title: 'Dune' });
    const res = await post(`/books/${book.id}/finish`, {}, { referer: `${base}/books/${book.id}` });
    expect(res.headers.get('location')).toBe(`/books/${book.id}`);
  });

  it('shows a book page with title, author, notes and a share link', async () => {
    const book = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'Line one\nLine two' });
    const res = await fetch(`${base}/books/${book.id}`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('<h2>Dune</h2>');
    expect(html).toContain('by Frank Herbert');
    expect(html).toContain('Line one\nLine two');
    expect(html).toContain(`value="${base}/books/${book.id}"`);
  });

  it('returns 404 for an unknown book', async () => {
    expect((await fetch(`${base}/books/nope`)).status).toBe(404);
    expect((await post('/books/nope/finish')).status).toBe(404);
    expect((await fetch(`${base}/books/%E0%A4%A`)).status).toBe(404);
  });

  it('rejects a book without a title and keeps what was typed', async () => {
    const res = await post('/books', { title: '  ', author: 'Someone' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Please give the book a title.');
    expect(html).toContain('value="Someone"');
  });

  it('escapes HTML in user input', async () => {
    const book = await addBook({ title: '<script>alert(1)</script>', notes: '"><img src=x>' });
    const page = await (await fetch(`${base}/books/${book.id}`)).text();
    const home = await (await fetch(base + '/')).text();
    for (const html of [page, home]) {
      expect(html).not.toContain('<script>alert(1)</script>');
      expect(html).not.toContain('<img src=x>');
    }
  });

  it('keeps books after a restart', async () => {
    const book = await addBook({ title: 'Dune', author: 'Frank Herbert' });
    await post(`/books/${book.id}/finish`);
    await stop();
    await start();

    const html = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(html).toContain('<h2>Dune</h2>');
    expect(html).toContain('Finished on');
  });

  it('refuses to start over a corrupt data file instead of wiping it', async () => {
    await writeFile(dataFile, '{not json');
    await expect(openStore(dataFile)).rejects.toThrow();
    expect(await readFile(dataFile, 'utf8')).toBe('{not json');
  });
});

